reference_solution:
def maximum_stock_budget_profit(present,future,budget):
    dp=[0]*(budget+1)
    for cost,sale in zip(present,future):
        profit=sale-cost
        if profit<=0:continue
        for money in range(budget,cost-1,-1):dp[money]=max(dp[money],dp[money-cost]+profit)
    return dp[budget]

